-- Create "rating_content_types" table
CREATE TABLE "rating_content_types" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "content_type" character varying NOT NULL, PRIMARY KEY ("id"));
-- Create index "ratingcontenttype_content_type" to table: "rating_content_types"
CREATE UNIQUE INDEX "ratingcontenttype_content_type" ON "rating_content_types" ("content_type");
-- Create "rating_settings" table
CREATE TABLE "rating_settings" ("id" bigint NOT NULL, "scale" bigint NOT NULL DEFAULT 5, "allow_guests" boolean NOT NULL DEFAULT false, "allow_change" boolean NOT NULL DEFAULT true, "allow_withdraw" boolean NOT NULL DEFAULT true, PRIMARY KEY ("id"));
-- Create "rating_votes" table
CREATE TABLE "rating_votes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "guest" character(64) NULL, "score" bigint NOT NULL, "scale" bigint NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "nid" bigint NOT NULL, "uid" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "rating_votes_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE, CONSTRAINT "rating_votes_users_user" FOREIGN KEY ("uid") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "idx_rating_votes_node_user" to table: "rating_votes"
CREATE UNIQUE INDEX "idx_rating_votes_node_user" ON "rating_votes" ("nid", "uid");
-- Create index "idx_rating_votes_node_guest" to table: "rating_votes"
CREATE UNIQUE INDEX "idx_rating_votes_node_guest" ON "rating_votes" ("nid", "guest");
-- Create index "ratingvote_uid" to table: "rating_votes"
CREATE INDEX "ratingvote_uid" ON "rating_votes" ("uid");
